import { total } from './cart.js';

// The printed wholesale price list gives the 5% bulk discount from 10 lines. It is
// pinned here so that changes to the shop cart's bulk threshold do not silently
// change what wholesale customers are invoiced.
const WHOLESALE_BULK_MIN_LINES = 10;

// Invoices for wholesale orders (#7). The amount due is the cart total under the
// rules of the printed price list wholesale customers order from —
// list price below 10 lines, 5% off from 10 lines, half a yen rounded up.
export function invoice(customer, items) {
  return { customer, due: total(items, 0, { bulkMinLines: WHOLESALE_BULK_MIN_LINES }) };
}

